let byDept = byName.sorted { $0.department < $1.department }
print(byDept.map(\.name))

struct Message {
    let id: Int
    let sentAt: Int
}
final class ChatHistory {
    private(set) var messages: [Message] = []
    func load(_ batch: [Message]) {
        for message in batch {
            messages.append(message)
            messages.sort { $0.sentAt < $1.sentAt }
        }
    }
}

